PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, description TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)), sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL UNIQUE, category_id TEXT REFERENCES categories(id) ON DELETE SET NULL, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, price_minor INTEGER NOT NULL CHECK (price_minor >= 0), currency TEXT NOT NULL DEFAULT 'IDR', stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0), status TEXT NOT NULL DEFAULT 'unavailable' CHECK (status IN ('available','unavailable','paused')), image_url TEXT, supplier_updated_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS products_category_status_idx ON products(category_id, status);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('admin','member','reseller')), email_verified_at TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS sessions (id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), invoice TEXT NOT NULL UNIQUE, idempotency_key TEXT NOT NULL, supplier_ref TEXT, total_minor INTEGER NOT NULL CHECK (total_minor >= 0), currency TEXT NOT NULL DEFAULT 'IDR', status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','failed','needs_review','cancelled')), supplier_request_state TEXT NOT NULL DEFAULT 'not_sent' CHECK (supplier_request_state IN ('not_sent','sent','unknown','confirmed')), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(user_id, idempotency_key));
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id TEXT REFERENCES products(id) ON DELETE SET NULL, product_name_snapshot TEXT NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price_minor INTEGER NOT NULL CHECK (unit_price_minor >= 0), line_total_minor INTEGER NOT NULL CHECK (line_total_minor >= 0));
CREATE TABLE IF NOT EXISTS delivery_credentials (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, ciphertext TEXT NOT NULL, encryption_key_version TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS deposits (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), invoice TEXT NOT NULL UNIQUE, amount_minor INTEGER NOT NULL CHECK (amount_minor > 0), unique_code INTEGER NOT NULL DEFAULT 0, total_minor INTEGER NOT NULL CHECK (total_minor > 0), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','paid','expired','cancelled','failed')), provider_reference TEXT, expires_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS wallet_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), reference_type TEXT NOT NULL, reference_id TEXT NOT NULL, direction TEXT NOT NULL CHECK (direction IN ('credit','debit')), amount_minor INTEGER NOT NULL CHECK (amount_minor > 0), currency TEXT NOT NULL DEFAULT 'IDR', created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(reference_type, reference_id, direction));
CREATE TABLE IF NOT EXISTS webhook_events (id TEXT PRIMARY KEY, provider TEXT NOT NULL, event_id TEXT NOT NULL, invoice TEXT, payload_redacted TEXT NOT NULL, processed_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(provider, event_id));
CREATE TABLE IF NOT EXISTS supplier_api_logs (id TEXT PRIMARY KEY, operation TEXT NOT NULL, http_status INTEGER, outcome TEXT NOT NULL, duration_ms INTEGER, error_code TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS reseller_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, markup_bps INTEGER NOT NULL DEFAULT 0 CHECK (markup_bps >= 0), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','suspended')), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, metadata_redacted TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS orders_user_created_idx ON orders(user_id, created_at);
CREATE INDEX IF NOT EXISTS wallet_ledger_user_idx ON wallet_ledger(user_id, created_at);
CREATE INDEX IF NOT EXISTS audit_logs_created_idx ON audit_logs(created_at);
